package live.linghe.privateinput;
import android.app.Instrumentation;import android.os.Bundle;import android.content.Context;import java.io.*;import java.security.*;import java.util.*;import java.util.zip.*;import org.json.JSONObject;
public final class DataSnapshot extends Instrumentation {
 private Bundle args;public void onCreate(Bundle data){super.onCreate(data);args=data;start();}
 private void files(File base,File file,ZipOutputStream zip,JSONObject manifest)throws Exception{if(file.isDirectory()){File[] list=file.listFiles();if(list!=null){Arrays.sort(list);for(File child:list)files(base,child,zip,manifest);}return;}String name=base.toURI().relativize(file.toURI()).getPath();MessageDigest sha=MessageDigest.getInstance("SHA-256");zip.putNextEntry(new ZipEntry(name));try(InputStream input=new FileInputStream(file)){byte[] buf=new byte[65536];int n;while((n=input.read(buf))>0){zip.write(buf,0,n);sha.update(buf,0,n);}}zip.closeEntry();StringBuilder text=new StringBuilder();for(byte b:sha.digest())text.append(String.format("%02x",b&255));manifest.put(name,text.toString());}
 public void onStart(){Bundle result=new Bundle();try{String label=args.getString("label","snapshot");if(!label.matches("[a-z0-9-]{1,40}"))throw new Exception("invalid label");Context app=getTargetContext();File base=app.getFilesDir().getParentFile(),external=app.getExternalFilesDir("delivery-backup");if(external==null)throw new IOException("external app storage unavailable");File output=new File(external,label+".zip");if(output.exists())throw new IOException("snapshot exists");JSONObject manifest=new JSONObject();try(ZipOutputStream zip=new ZipOutputStream(new FileOutputStream(output))){for(String scope:new String[]{"files","shared_prefs","databases","no_backup"}){File dir=new File(base,scope);if(dir.exists())files(base,dir,zip,manifest);}zip.putNextEntry(new ZipEntry("snapshot-manifest.json"));zip.write(manifest.toString().getBytes("UTF-8"));zip.closeEntry();}result.putString("result","Passed");result.putInt("persistentFiles",manifest.length());result.putString("zip",output.getAbsolutePath());}catch(Throwable e){result.putString("result","Failed");result.putString("error",e.getClass().getSimpleName()+": "+e.getMessage());}finish(result.getString("result").equals("Passed")?-1:0,result);}
}
